class Solution {
  public int countValidSubsets(int[] parent, int[] nums, int k) {
    final long MOD = 1_000_000_007L;
    int n = parent.length;
    long[][] free = new long[n][k], skipOnly = new long[n][k];
    for (int i = 0; i < n; i++) {
      free[i][0] = 1;
      skipOnly[i][0] = 1;
    }
    long[] notTaken = new long[k], taken = new long[k];
    for (int v = n - 1; v >= 0; v--) {
      notTaken = free[v];
      taken = new long[k];
      int shift = nums[v] % k;
      for (int r = 0; r < k; r++) taken[(r + shift) % k] = skipOnly[v][r];
      if (v == 0) break;
      int p = parent[v];
      long[] childAny = new long[k];
      for (int r = 0; r < k; r++) childAny[r] = (notTaken[r] + taken[r]) % MOD;
      free[p] = convolve(free[p], childAny, k, MOD);
      skipOnly[p] = convolve(skipOnly[p], notTaken, k, MOD);
    }
    return (int) (((notTaken[0] + taken[0] - 1) % MOD + MOD) % MOD);
  }

  private static long[] convolve(long[] a, long[] b, int k, long mod) {
    long[] res = new long[k];
    for (int i = 0; i < k; i++) {
      if (a[i] == 0) continue;
      for (int j = 0; j < k; j++) {
        int t = i + j >= k ? i + j - k : i + j;
        res[t] = (res[t] + a[i] * b[j]) % mod;
      }
    }
    return res;
  }
}
